package avl

//----------------------------------------
// Node

// Node represents a node in an AVL tree.
type Node struct {
	key       string // key is the unique identifier for the node.
	value     any    // value is the data stored in the node.
	height    int8   // height is the height of the node in the tree.
	size      int    // size is the number of leaf nodes (key-value pairs) in the subtree rooted at this node.
	leftNode  *Node  // leftNode is the left child of the node.
	rightNode *Node  // rightNode is the right child of the node.
}

// NewNode creates a new node with the given key and value.
func NewNode(key string, value any) *Node {
	return &Node{
		key:    key,
		value:  value,
		height: 0,
		size:   1,
	}
}

// Size returns the size of the subtree rooted at the node.
func (node *Node) Size() int {
	if node == nil {
		return 0
	}
	return node.size
}

// IsLeaf checks if the node is a leaf node (has no children).
func (node *Node) IsLeaf() bool {
	return node.height == 0
}

// Key returns the key of the node.
func (node *Node) Key() string {
	return node.key
}

// Value returns the value of the node.
func (node *Node) Value() any {
	return node.value
}

func (node *Node) _copy() *Node {
	if node.height == 0 {
		panic("Why are you copying a value node?")
	}
	return &Node{
		key:       node.key,
		height:    node.height,
		size:      node.size,
		leftNode:  node.leftNode,
		rightNode: node.rightNode,
	}
}

// Has checks if a node with the given key exists in the subtree rooted at the node.
func (node *Node) Has(key string) (has bool) {
	if node == nil {
		return false
	}
	if node.key == key {
		return true
	}
	if node.height == 0 {
		return false
	} else {
		if key < node.key {
			return node.getLeftNode().Has(key)
		} else {
			return node.getRightNode().Has(key)
		}
	}
}

// Get searches for a node with the given key in the subtree rooted at the node
// and returns its index, value, and whether it exists.
func (node *Node) Get(key string) (index int, value any, exists bool) {
	if node == nil {
		return 0, nil, false
	}

	if node.height == 0 {
		if node.key == key {
			return 0, node.value, true
		} else if node.key < key {
			return 1, nil, false
		} else {
			return 0, nil, false
		}
	} else {
		if key < node.key {
			return node.getLeftNode().Get(key)
		} else {
			rightNode := node.getRightNode()
			index, value, exists = rightNode.Get(key)
			index += node.size - rightNode.size
			return index, value, exists
		}
	}
}

// GetByIndex retrieves the key-value pair of the node at the given index
// in the subtree rooted at the node.
func (node *Node) GetByIndex(index int) (key string, value any) {
	if index < 0 {
		panic("GetByIndex: negative index not allowed")
	}

	if node.height == 0 {
		if index != 0 {
			panic("GetByIndex asked for invalid index")
		}
		return node.key, node.value
	} else {
		// TODO: could improve this by storing the sizes
		leftNode := node.getLeftNode()
		if index < leftNode.size {
			return leftNode.GetByIndex(index)
		} else {
			return node.getRightNode().GetByIndex(index - leftNode.size)
		}
	}
}

// Set inserts a new node with the given key-value pair into the subtree rooted at the node,
// and returns the new root of the subtree and whether an existing node was updated.
//
// XXX consider a better way to do this... perhaps split Node from Node.
func (node *Node) Set(key string, value any) (newSelf *Node, updated bool) {
	if node == nil {
		return NewNode(key, value), false
	}
	if node.height == 0 {
		if key < node.key {
			return &Node{
				key:       node.key,
				height:    1,
				size:      2,
				leftNode:  NewNode(key, value),
				rightNode: node,
			}, false
		} else if key == node.key {
			return NewNode(key, value), true
		} else {
			return &Node{
				key:       key,
				height:    1,
				size:      2,
				leftNode:  node,
				rightNode: NewNode(key, value),
			}, false
		}
	} else {
		node = node._copy()
		if key < node.key {
			node.leftNode, updated = node.getLeftNode().Set(key, value)
		} else {
			node.rightNode, updated = node.getRightNode().Set(key, value)
		}
		if updated {
			return node, updated
		} else {
			node.calcHeightAndSize()
			return node.balance(), updated
		}
	}
}

// Remove deletes the node with the given key from the subtree rooted at the node.
// returns the new root of the subtree, the new leftmost leaf key (if changed),
// the removed value and the removal was successful.
func (node *Node) Remove(key string) (
	newNode *Node, newKey string, value any, removed bool,
) {
	if node == nil {
		return nil, "", nil, false
	}
	if node.height == 0 {
		if key == node.key {
			return nil, "", node.value, true
		} else {
			return node, "", nil, false
		}
	} else {
		if key < node.key {
			var newLeftNode *Node
			newLeftNode, newKey, value, removed = node.getLeftNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newLeftNode == nil { // left node held value, was removed
				return node.rightNode, node.key, value, true
			}
			node = node._copy()
			node.leftNode = newLeftNode
			node.calcHeightAndSize()
			node = node.balance()
			return node, newKey, value, true
		} else {
			var newRightNode *Node
			newRightNode, newKey, value, removed = node.getRightNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newRightNode == nil { // right node held value, was removed
				return node.leftNode, "", value, true
			}
			node = node._copy()
			node.rightNode = newRightNode
			if newKey != "" {
				node.key = newKey
			}
			node.calcHeightAndSize()
			node = node.balance()
			return node, "", value, true
		}
	}
}

func (node *Node) getLeftNode() *Node {
	return node.leftNode
}

func (node *Node) getRightNode() *Node {
	return node.rightNode
}

// rotateRight performs a right rotation on the node and returns the new root.
// NOTE: overwrites node
// TODO: optimize balance & rotate
func (node *Node) rotateRight() *Node {
	node = node._copy()
	l := node.getLeftNode()
	_l := l._copy()

	_lrCached := _l.rightNode
	_l.rightNode = node
	node.leftNode = _lrCached

	node.calcHeightAndSize()
	_l.calcHeightAndSize()

	return _l
}

// rotateLeft performs a left rotation on the node and returns the new root.
// NOTE: overwrites node
// TODO: optimize balance & rotate
func (node *Node) rotateLeft() *Node {
	node = node._copy()
	r := node.getRightNode()
	_r := r._copy()

	_rlCached := _r.leftNode
	_r.leftNode = node
	node.rightNode = _rlCached

	node.calcHeightAndSize()
	_r.calcHeightAndSize()

	return _r
}

// calcHeightAndSize updates the height and size of the node based on its children.
// NOTE: mutates height and size
func (node *Node) calcHeightAndSize() {
	node.height = maxInt8(node.getLeftNode().height, node.getRightNode().height) + 1
	node.size = node.getLeftNode().size + node.getRightNode().size
}

// calcBalance calculates the balance factor of the node.
func (node *Node) calcBalance() int {
	return int(node.getLeftNode().height) - int(node.getRightNode().height)
}

// balance balances the subtree rooted at the node and returns the new root.
// NOTE: assumes that node can be modified
// TODO: optimize balance & rotate
func (node *Node) balance() (newSelf *Node) {
	balance := node.calcBalance()
	if balance > 1 {
		if node.getLeftNode().calcBalance() >= 0 {
			// Left Left Case
			return node.rotateRight()
		} else {
			// Left Right Case
			left := node.getLeftNode()
			node.leftNode = left.rotateLeft()
			return node.rotateRight()
		}
	}
	if balance < -1 {
		if node.getRightNode().calcBalance() <= 0 {
			// Right Right Case
			return node.rotateLeft()
		} else {
			// Right Left Case
			right := node.getRightNode()
			node.rightNode = right.rotateRight()
			return node.rotateLeft()
		}
	}
	// Nothing changed
	return node
}

// Shortcut for TraverseInRange.
func (node *Node) Iterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, true, true, cb)
}

// Shortcut for TraverseInRange.
func (node *Node) ReverseIterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, false, true, cb)
}

// TraverseInRange traverses all nodes, including inner nodes.
// Start is inclusive and end is exclusive when ascending,
// Start and end are inclusive when descending.
// Empty start and empty end denote no start and no end.
// If leavesOnly is true, only visit leaf nodes.
// NOTE: To simulate an exclusive reverse traversal,
// just append 0x00 to start.
func (node *Node) TraverseInRange(start, end string, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}
	afterStart := (start == "" || start < node.key)
	startOrAfter := (start == "" || start <= node.key)
	beforeEnd := false
	if ascending {
		beforeEnd = (end == "" || node.key < end)
	} else {
		beforeEnd = (end == "" || node.key <= end)
	}

	// Run callback per inner/leaf node.
	stop := false
	if (!node.IsLeaf() && !leavesOnly) ||
		(node.IsLeaf() && startOrAfter && beforeEnd) {
		stop = cb(node)
		if stop {
			return stop
		}
	}
	if node.IsLeaf() {
		return stop
	}

	if ascending {
		// check lower nodes, then higher
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	} else {
		// check the higher nodes first
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	}

	return stop
}

// TraverseByOffset traverses all nodes, including inner nodes.
// A limit of math.MaxInt means no limit.
func (node *Node) TraverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}

	// Clamp negative offset to 0; otherwise `delta := first.size - offset`
	// over-counts and silently drops nodes.
	if offset < 0 {
		offset = 0
	}

	// fast paths. these happen only if TraverseByOffset is called directly on a leaf.
	if limit <= 0 || offset >= node.size {
		return false
	}
	if node.IsLeaf() {
		if offset > 0 {
			return false
		}
		return cb(node)
	}

	// go to the actual recursive function.
	return node.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

// TraverseByOffset traverses the subtree rooted at the node by offset and limit,
// in either ascending or descending order, and applies the callback function to each traversed node.
// If leavesOnly is true, only leaf nodes are visited.
func (node *Node) traverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	// caller guarantees: offset < node.size; limit > 0.
	if !leavesOnly {
		if cb(node) {
			return true // Stop traversal if callback returns true
		}
	}
	first, second := node.getLeftNode(), node.getRightNode()
	if !ascending {
		first, second = second, first
	}
	if first.IsLeaf() {
		// either run or skip, based on offset
		if offset > 0 {
			offset--
		} else {
			if cb(first) {
				return true // Stop traversal if callback returns true
			}
			limit--
			if limit <= 0 {
				return true // Stop traversal when limit is reached
			}
		}
	} else {
		// possible cases:
		// 1 the offset given skips the first node entirely
		// 2 the offset skips none or part of the first node, but the limit requires some of the second node.
		// 3 the offset skips none or part of the first node, and the limit stops our search on the first node.
		if offset >= first.size {
			offset -= first.size // 1
		} else {
			if first.traverseByOffset(offset, limit, ascending, leavesOnly, cb) {
				return true
			}
			// number of leaves which could actually be called from inside
			delta := first.size - offset
			offset = 0
			if delta >= limit {
				return true // 3
			}
			limit -= delta // 2
		}
	}

	// because of the caller guarantees and the way we handle the first node,
	// at this point we know that limit > 0 and there must be some values in
	// this second node that we include.

	// => if the second node is a leaf, it has to be included.
	if second.IsLeaf() {
		return cb(second)
	}
	// => if it is not a leaf, it will still be enough to recursively call this
	// function with the updated offset and limit
	return second.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

// Only used in testing...
func (node *Node) lmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getLeftNode().lmd()
}

// Only used in testing...
func (node *Node) rmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getRightNode().rmd()
}

func maxInt8(a, b int8) int8 {
	if a > b {
		return a
	}
	return b
}

// Package avl is a vendored copy of gno.land/p/nt/avl/v0, pinned under
// this project's own namespace instead of imported from the shared
// stdlib. Necessary because that shared package is NOT the same across
// gno.land networks: testnet's Tree.Get returns a single value (any),
// while Beta Mainnet's already returns two (value any, exists bool) —
// confirmed directly from each chain's own deployed source, not
// documentation. Code built against one signature fails to compile on
// the other, so this project can't depend on the shared import staying
// consistent across every network it deploys to. Vendoring under our
// own address means every deploy — local, testnet, Beta Mainnet, or
// wherever gno.land goes next — gets the exact same, single-return
// Get() this project's code (grc721 + nftminter) is written against,
// regardless of whatever the shared package looks like on that chain.
//
// Copied verbatim from gno.land/p/nt/avl/v0 (testnet's version, single-
// return Get) as of 2026-08 — not reimplemented, to avoid introducing
// any behavioral drift from the tested original.
package avl

type ITree interface {
	// read operations

	Size() int
	Has(key string) bool
	Get(key string) any
	GetByIndex(index int) (key string, value any)
	Iterate(start, end string, cb IterCbFn) bool
	ReverseIterate(start, end string, cb IterCbFn) bool
	IterateByOffset(offset int, count int, cb IterCbFn) bool
	ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool

	// write operations

	Set(key string, value any) (updated bool)
	Remove(key string) (value any, removed bool)
}

type IterCbFn func(key string, value any) bool

//----------------------------------------
// Tree

// The zero struct can be used as an empty tree.
type Tree struct {
	node *Node
}

// NewTree creates a new empty AVL tree.
func NewTree() *Tree {
	return &Tree{
		node: nil,
	}
}

// Size returns the number of key-value pair in the tree.
func (tree *Tree) Size() int {
	return tree.node.Size()
}

// Has checks whether a key exists in the tree.
// It returns true if the key exists, otherwise false.
func (tree *Tree) Has(key string) (has bool) {
	return tree.node.Has(key)
}

// Get retrieves the value associated with the given key.
// It returns the value if the key exists, or nil if it doesn't.
// Note that a key stored with a nil value is indistinguishable
// from an absent key; use Has to check for existence.
// This allows for a simpler usage pattern with type assertions:
//
//	if value, ok := tree.Get("key").(MyType); ok {
//	    // use value
//	}
func (tree *Tree) Get(key string) any {
	_, value, _ := tree.node.Get(key)
	return value
}

// GetByIndex retrieves the key-value pair at the specified index in the tree.
// It returns the key and value at the given index.
func (tree *Tree) GetByIndex(index int) (key string, value any) {
	return tree.node.GetByIndex(index)
}

// Set inserts a key-value pair into the tree.
// If the key already exists, the value will be updated.
// It returns a boolean indicating whether the key was newly inserted or updated.
func (tree *Tree) Set(key string, value any) (updated bool) {
	newnode, updated := tree.node.Set(key, value)
	tree.node = newnode
	return updated
}

// Remove removes a key-value pair from the tree.
// It returns the removed value and a boolean indicating whether the key was found and removed.
func (tree *Tree) Remove(key string) (value any, removed bool) {
	newnode, _, value, removed := tree.node.Remove(key)
	tree.node = newnode
	return value, removed
}

// Iterate performs an in-order traversal of the tree within the specified key range.
// It calls the provided callback function for each key-value pair encountered.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) Iterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// ReverseIterate performs a reverse in-order traversal of the tree within the specified key range.
// It calls the provided callback function for each key-value pair encountered.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) ReverseIterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// IterateByOffset performs an in-order traversal of the tree starting from the specified offset.
// It calls the provided callback function for each key-value pair encountered, up to the specified count.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) IterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// ReverseIterateByOffset performs a reverse in-order traversal of the tree starting from the specified offset.
// It calls the provided callback function for each key-value pair encountered, up to the specified count.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// Verify that Tree implements TreeInterface
var _ ITree = (*Tree)(nil)

// Package token is a fixed-supply GRC20-shaped fungible token realm.
//
// The full supply (TotalSupplyConst) is minted once, to the deploying
// address, inside init() — there is no ongoing or public Mint function
// afterward, and no way to create more supply later.
//
// Deliberately not a dependency on gno.land/p/demo/tokens/grc20: that
// package's NewToken constructor, Teller interface, and Token.ID()
// collision-safety were all found to diverge between gno.land networks
// (confirmed directly against each chain's deployed source, not
// assumed — see ~/gno-land-dev-notes.md's discovery log). Everything
// here is self-implemented on a vendored, network-agnostic avl.Tree
// instead — see gno.land/p/<addr>/avl/tree.gno's own header comment for
// why that package is vendored rather than imported from
// gno.land/p/nt/avl/v0.
package token

import (
	unsaferealm "chain/runtime/unsafe"
	"chain"
	"errors"
	"strconv"

	"gno.land/p/g1avv0u2d45d8lf8ywqxt8t867npwp4zvdxw2fl2/avl"
)

const (
	MintEvent     = "Mint"
	TransferEvent = "Transfer"
	ApprovalEvent = "Approval"
)

const (
	TokenName     = "Sample Token"
	TokenSymbol   = "SAMPLE"
	TokenDecimals = 6

	TotalSupplyConst int64 = 1_000_000
)

var (
	creator address = "g1avv0u2d45d8lf8ywqxt8t867npwp4zvdxw2fl2"

	balances   avl.Tree // address string -> int64
	allowances avl.Tree // "owner:spender" string -> int64
)

var (
	ErrInsufficientBalance   = errors.New("insufficient balance")
	ErrInsufficientAllowance = errors.New("insufficient allowance")
	ErrInvalidAddress        = errors.New("invalid address")
	ErrCannotTransferToSelf  = errors.New("cannot transfer to self")
	ErrInvalidAmount         = errors.New("invalid amount")
)

func init(cur realm) {
	balances.Set(creator.String(), TotalSupplyConst)
	chain.Emit(
		MintEvent,
		"to", creator.String(),
		"amount", strconv.FormatInt(TotalSupplyConst, 10),
	)
}

func callerAddress() address {
	return unsaferealm.PreviousRealm().Address()
}

func Name() string       { return TokenName }
func Symbol() string     { return TokenSymbol }
func Decimals() int      { return TokenDecimals }
func TotalSupply() int64 { return TotalSupplyConst }

func BalanceOf(addr address) int64 {
	v := balances.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

func Allowance(owner, spender address) int64 {
	v := allowances.Get(allowanceKey(owner, spender))
	if v == nil {
		return 0
	}
	return v.(int64)
}

func allowanceKey(owner, spender address) string {
	return owner.String() + ":" + spender.String()
}

func Transfer(cur realm, to address, amount int64) error {
	return transfer(callerAddress(), to, amount)
}

func Approve(cur realm, spender address, amount int64) error {
	owner := callerAddress()
	if !spender.IsValid() {
		return ErrInvalidAddress
	}
	if amount < 0 {
		return ErrInvalidAmount
	}
	allowances.Set(allowanceKey(owner, spender), amount)
	chain.Emit(
		ApprovalEvent,
		"owner", owner.String(),
		"spender", spender.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return nil
}

func TransferFrom(cur realm, from, to address, amount int64) error {
	spender := callerAddress()
	current := Allowance(from, spender)
	if current < amount {
		return ErrInsufficientAllowance
	}
	if err := transfer(from, to, amount); err != nil {
		return err
	}
	allowances.Set(allowanceKey(from, spender), current-amount)
	return nil
}

func transfer(from, to address, amount int64) error {
	if !to.IsValid() {
		return ErrInvalidAddress
	}
	if from == to {
		return ErrCannotTransferToSelf
	}
	if amount <= 0 {
		return ErrInvalidAmount
	}
	fromBal := BalanceOf(from)
	if fromBal < amount {
		return ErrInsufficientBalance
	}
	balances.Set(from.String(), fromBal-amount)
	balances.Set(to.String(), BalanceOf(to)+amount)
	chain.Emit(
		TransferEvent,
		"from", from.String(),
		"to", to.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return nil
}

func Render(path string) string {
	b := "# " + TokenName + " (" + TokenSymbol + ")\n\n"
	b += "* **Decimals**: " + strconv.Itoa(TokenDecimals) + "\n"
	b += "* **Total supply**: " + strconv.FormatInt(TotalSupply(), 10) + "\n"
	b += "* **Creator**: " + creator.String() + "\n"
	return b
}

package avl

//----------------------------------------
// Node

// Node represents a node in an AVL tree.
type Node struct {
	key       string // key is the unique identifier for the node.
	value     any    // value is the data stored in the node.
	height    int8   // height is the height of the node in the tree.
	size      int    // size is the number of leaf nodes (key-value pairs) in the subtree rooted at this node.
	leftNode  *Node  // leftNode is the left child of the node.
	rightNode *Node  // rightNode is the right child of the node.
}

// NewNode creates a new node with the given key and value.
func NewNode(key string, value any) *Node {
	return &Node{
		key:    key,
		value:  value,
		height: 0,
		size:   1,
	}
}

// Size returns the size of the subtree rooted at the node.
func (node *Node) Size() int {
	if node == nil {
		return 0
	}
	return node.size
}

// IsLeaf checks if the node is a leaf node (has no children).
func (node *Node) IsLeaf() bool {
	return node.height == 0
}

// Key returns the key of the node.
func (node *Node) Key() string {
	return node.key
}

// Value returns the value of the node.
func (node *Node) Value() any {
	return node.value
}

func (node *Node) _copy() *Node {
	if node.height == 0 {
		panic("Why are you copying a value node?")
	}
	return &Node{
		key:       node.key,
		height:    node.height,
		size:      node.size,
		leftNode:  node.leftNode,
		rightNode: node.rightNode,
	}
}

// Has checks if a node with the given key exists in the subtree rooted at the node.
func (node *Node) Has(key string) (has bool) {
	if node == nil {
		return false
	}
	if node.key == key {
		return true
	}
	if node.height == 0 {
		return false
	} else {
		if key < node.key {
			return node.getLeftNode().Has(key)
		} else {
			return node.getRightNode().Has(key)
		}
	}
}

// Get searches for a node with the given key in the subtree rooted at the node
// and returns its index, value, and whether it exists.
func (node *Node) Get(key string) (index int, value any, exists bool) {
	if node == nil {
		return 0, nil, false
	}

	if node.height == 0 {
		if node.key == key {
			return 0, node.value, true
		} else if node.key < key {
			return 1, nil, false
		} else {
			return 0, nil, false
		}
	} else {
		if key < node.key {
			return node.getLeftNode().Get(key)
		} else {
			rightNode := node.getRightNode()
			index, value, exists = rightNode.Get(key)
			index += node.size - rightNode.size
			return index, value, exists
		}
	}
}

// GetByIndex retrieves the key-value pair of the node at the given index
// in the subtree rooted at the node.
func (node *Node) GetByIndex(index int) (key string, value any) {
	if index < 0 {
		panic("GetByIndex: negative index not allowed")
	}

	if node.height == 0 {
		if index != 0 {
			panic("GetByIndex asked for invalid index")
		}
		return node.key, node.value
	} else {
		// TODO: could improve this by storing the sizes
		leftNode := node.getLeftNode()
		if index < leftNode.size {
			return leftNode.GetByIndex(index)
		} else {
			return node.getRightNode().GetByIndex(index - leftNode.size)
		}
	}
}

// Set inserts a new node with the given key-value pair into the subtree rooted at the node,
// and returns the new root of the subtree and whether an existing node was updated.
//
// XXX consider a better way to do this... perhaps split Node from Node.
func (node *Node) Set(key string, value any) (newSelf *Node, updated bool) {
	if node == nil {
		return NewNode(key, value), false
	}
	if node.height == 0 {
		if key < node.key {
			return &Node{
				key:       node.key,
				height:    1,
				size:      2,
				leftNode:  NewNode(key, value),
				rightNode: node,
			}, false
		} else if key == node.key {
			return NewNode(key, value), true
		} else {
			return &Node{
				key:       key,
				height:    1,
				size:      2,
				leftNode:  node,
				rightNode: NewNode(key, value),
			}, false
		}
	} else {
		node = node._copy()
		if key < node.key {
			node.leftNode, updated = node.getLeftNode().Set(key, value)
		} else {
			node.rightNode, updated = node.getRightNode().Set(key, value)
		}
		if updated {
			return node, updated
		} else {
			node.calcHeightAndSize()
			return node.balance(), updated
		}
	}
}

// Remove deletes the node with the given key from the subtree rooted at the node.
// returns the new root of the subtree, the new leftmost leaf key (if changed),
// the removed value and the removal was successful.
func (node *Node) Remove(key string) (
	newNode *Node, newKey string, value any, removed bool,
) {
	if node == nil {
		return nil, "", nil, false
	}
	if node.height == 0 {
		if key == node.key {
			return nil, "", node.value, true
		} else {
			return node, "", nil, false
		}
	} else {
		if key < node.key {
			var newLeftNode *Node
			newLeftNode, newKey, value, removed = node.getLeftNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newLeftNode == nil { // left node held value, was removed
				return node.rightNode, node.key, value, true
			}
			node = node._copy()
			node.leftNode = newLeftNode
			node.calcHeightAndSize()
			node = node.balance()
			return node, newKey, value, true
		} else {
			var newRightNode *Node
			newRightNode, newKey, value, removed = node.getRightNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newRightNode == nil { // right node held value, was removed
				return node.leftNode, "", value, true
			}
			node = node._copy()
			node.rightNode = newRightNode
			if newKey != "" {
				node.key = newKey
			}
			node.calcHeightAndSize()
			node = node.balance()
			return node, "", value, true
		}
	}
}

func (node *Node) getLeftNode() *Node {
	return node.leftNode
}

func (node *Node) getRightNode() *Node {
	return node.rightNode
}

// rotateRight performs a right rotation on the node and returns the new root.
// NOTE: overwrites node
// TODO: optimize balance & rotate
func (node *Node) rotateRight() *Node {
	node = node._copy()
	l := node.getLeftNode()
	_l := l._copy()

	_lrCached := _l.rightNode
	_l.rightNode = node
	node.leftNode = _lrCached

	node.calcHeightAndSize()
	_l.calcHeightAndSize()

	return _l
}

// rotateLeft performs a left rotation on the node and returns the new root.
// NOTE: overwrites node
// TODO: optimize balance & rotate
func (node *Node) rotateLeft() *Node {
	node = node._copy()
	r := node.getRightNode()
	_r := r._copy()

	_rlCached := _r.leftNode
	_r.leftNode = node
	node.rightNode = _rlCached

	node.calcHeightAndSize()
	_r.calcHeightAndSize()

	return _r
}

// calcHeightAndSize updates the height and size of the node based on its children.
// NOTE: mutates height and size
func (node *Node) calcHeightAndSize() {
	node.height = maxInt8(node.getLeftNode().height, node.getRightNode().height) + 1
	node.size = node.getLeftNode().size + node.getRightNode().size
}

// calcBalance calculates the balance factor of the node.
func (node *Node) calcBalance() int {
	return int(node.getLeftNode().height) - int(node.getRightNode().height)
}

// balance balances the subtree rooted at the node and returns the new root.
// NOTE: assumes that node can be modified
// TODO: optimize balance & rotate
func (node *Node) balance() (newSelf *Node) {
	balance := node.calcBalance()
	if balance > 1 {
		if node.getLeftNode().calcBalance() >= 0 {
			// Left Left Case
			return node.rotateRight()
		} else {
			// Left Right Case
			left := node.getLeftNode()
			node.leftNode = left.rotateLeft()
			return node.rotateRight()
		}
	}
	if balance < -1 {
		if node.getRightNode().calcBalance() <= 0 {
			// Right Right Case
			return node.rotateLeft()
		} else {
			// Right Left Case
			right := node.getRightNode()
			node.rightNode = right.rotateRight()
			return node.rotateLeft()
		}
	}
	// Nothing changed
	return node
}

// Shortcut for TraverseInRange.
func (node *Node) Iterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, true, true, cb)
}

// Shortcut for TraverseInRange.
func (node *Node) ReverseIterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, false, true, cb)
}

// TraverseInRange traverses all nodes, including inner nodes.
// Start is inclusive and end is exclusive when ascending,
// Start and end are inclusive when descending.
// Empty start and empty end denote no start and no end.
// If leavesOnly is true, only visit leaf nodes.
// NOTE: To simulate an exclusive reverse traversal,
// just append 0x00 to start.
func (node *Node) TraverseInRange(start, end string, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}
	afterStart := (start == "" || start < node.key)
	startOrAfter := (start == "" || start <= node.key)
	beforeEnd := false
	if ascending {
		beforeEnd = (end == "" || node.key < end)
	} else {
		beforeEnd = (end == "" || node.key <= end)
	}

	// Run callback per inner/leaf node.
	stop := false
	if (!node.IsLeaf() && !leavesOnly) ||
		(node.IsLeaf() && startOrAfter && beforeEnd) {
		stop = cb(node)
		if stop {
			return stop
		}
	}
	if node.IsLeaf() {
		return stop
	}

	if ascending {
		// check lower nodes, then higher
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	} else {
		// check the higher nodes first
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	}

	return stop
}

// TraverseByOffset traverses all nodes, including inner nodes.
// A limit of math.MaxInt means no limit.
func (node *Node) TraverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}

	// Clamp negative offset to 0; otherwise `delta := first.size - offset`
	// over-counts and silently drops nodes.
	if offset < 0 {
		offset = 0
	}

	// fast paths. these happen only if TraverseByOffset is called directly on a leaf.
	if limit <= 0 || offset >= node.size {
		return false
	}
	if node.IsLeaf() {
		if offset > 0 {
			return false
		}
		return cb(node)
	}

	// go to the actual recursive function.
	return node.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

// TraverseByOffset traverses the subtree rooted at the node by offset and limit,
// in either ascending or descending order, and applies the callback function to each traversed node.
// If leavesOnly is true, only leaf nodes are visited.
func (node *Node) traverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	// caller guarantees: offset < node.size; limit > 0.
	if !leavesOnly {
		if cb(node) {
			return true // Stop traversal if callback returns true
		}
	}
	first, second := node.getLeftNode(), node.getRightNode()
	if !ascending {
		first, second = second, first
	}
	if first.IsLeaf() {
		// either run or skip, based on offset
		if offset > 0 {
			offset--
		} else {
			if cb(first) {
				return true // Stop traversal if callback returns true
			}
			limit--
			if limit <= 0 {
				return true // Stop traversal when limit is reached
			}
		}
	} else {
		// possible cases:
		// 1 the offset given skips the first node entirely
		// 2 the offset skips none or part of the first node, but the limit requires some of the second node.
		// 3 the offset skips none or part of the first node, and the limit stops our search on the first node.
		if offset >= first.size {
			offset -= first.size // 1
		} else {
			if first.traverseByOffset(offset, limit, ascending, leavesOnly, cb) {
				return true
			}
			// number of leaves which could actually be called from inside
			delta := first.size - offset
			offset = 0
			if delta >= limit {
				return true // 3
			}
			limit -= delta // 2
		}
	}

	// because of the caller guarantees and the way we handle the first node,
	// at this point we know that limit > 0 and there must be some values in
	// this second node that we include.

	// => if the second node is a leaf, it has to be included.
	if second.IsLeaf() {
		return cb(second)
	}
	// => if it is not a leaf, it will still be enough to recursively call this
	// function with the updated offset and limit
	return second.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

// Only used in testing...
func (node *Node) lmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getLeftNode().lmd()
}

// Only used in testing...
func (node *Node) rmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getRightNode().rmd()
}

func maxInt8(a, b int8) int8 {
	if a > b {
		return a
	}
	return b
}

// Package avl is a vendored copy of gno.land/p/nt/avl/v0, pinned under
// this project's own namespace instead of imported from the shared
// stdlib. Necessary because that shared package is NOT the same across
// gno.land networks: testnet's Tree.Get returns a single value (any),
// while Beta Mainnet's already returns two (value any, exists bool) —
// confirmed directly from each chain's own deployed source, not
// documentation. Code built against one signature fails to compile on
// the other, so this project can't depend on the shared import staying
// consistent across every network it deploys to. Vendoring under our
// own address means every deploy — local, testnet, Beta Mainnet, or
// wherever gno.land goes next — gets the exact same, single-return
// Get() this project's code (grc721 + nftminter) is written against,
// regardless of whatever the shared package looks like on that chain.
//
// Copied verbatim from gno.land/p/nt/avl/v0 (testnet's version, single-
// return Get) as of 2026-08 — not reimplemented, to avoid introducing
// any behavioral drift from the tested original.
package avl

type ITree interface {
	// read operations

	Size() int
	Has(key string) bool
	Get(key string) any
	GetByIndex(index int) (key string, value any)
	Iterate(start, end string, cb IterCbFn) bool
	ReverseIterate(start, end string, cb IterCbFn) bool
	IterateByOffset(offset int, count int, cb IterCbFn) bool
	ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool

	// write operations

	Set(key string, value any) (updated bool)
	Remove(key string) (value any, removed bool)
}

type IterCbFn func(key string, value any) bool

//----------------------------------------
// Tree

// The zero struct can be used as an empty tree.
type Tree struct {
	node *Node
}

// NewTree creates a new empty AVL tree.
func NewTree() *Tree {
	return &Tree{
		node: nil,
	}
}

// Size returns the number of key-value pair in the tree.
func (tree *Tree) Size() int {
	return tree.node.Size()
}

// Has checks whether a key exists in the tree.
// It returns true if the key exists, otherwise false.
func (tree *Tree) Has(key string) (has bool) {
	return tree.node.Has(key)
}

// Get retrieves the value associated with the given key.
// It returns the value if the key exists, or nil if it doesn't.
// Note that a key stored with a nil value is indistinguishable
// from an absent key; use Has to check for existence.
// This allows for a simpler usage pattern with type assertions:
//
//	if value, ok := tree.Get("key").(MyType); ok {
//	    // use value
//	}
func (tree *Tree) Get(key string) any {
	_, value, _ := tree.node.Get(key)
	return value
}

// GetByIndex retrieves the key-value pair at the specified index in the tree.
// It returns the key and value at the given index.
func (tree *Tree) GetByIndex(index int) (key string, value any) {
	return tree.node.GetByIndex(index)
}

// Set inserts a key-value pair into the tree.
// If the key already exists, the value will be updated.
// It returns a boolean indicating whether the key was newly inserted or updated.
func (tree *Tree) Set(key string, value any) (updated bool) {
	newnode, updated := tree.node.Set(key, value)
	tree.node = newnode
	return updated
}

// Remove removes a key-value pair from the tree.
// It returns the removed value and a boolean indicating whether the key was found and removed.
func (tree *Tree) Remove(key string) (value any, removed bool) {
	newnode, _, value, removed := tree.node.Remove(key)
	tree.node = newnode
	return value, removed
}

// Iterate performs an in-order traversal of the tree within the specified key range.
// It calls the provided callback function for each key-value pair encountered.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) Iterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// ReverseIterate performs a reverse in-order traversal of the tree within the specified key range.
// It calls the provided callback function for each key-value pair encountered.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) ReverseIterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// IterateByOffset performs an in-order traversal of the tree starting from the specified offset.
// It calls the provided callback function for each key-value pair encountered, up to the specified count.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) IterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// ReverseIterateByOffset performs a reverse in-order traversal of the tree starting from the specified offset.
// It calls the provided callback function for each key-value pair encountered, up to the specified count.
// If the callback returns true, the iteration is stopped.
func (tree *Tree) ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

// Verify that Tree implements TreeInterface
var _ ITree = (*Tree)(nil)

// Package tokenfactory is a shared realm that mints fixed-supply
// GRC20-shaped fungible tokens on demand — an alternative to
// gno-token-minter's other design (gno.land/r/<addr>/token), where each
// creator deploys their own dedicated avl+token realm pair.
//
// Deployed exactly once, ever, under this project's own address. After
// that, creating a new token costs one MsgCall (New) instead of two
// MsgAddPackage deploys — see this project's design notes for the real
// measured cost comparison between the two approaches.
//
// Every token created here is fixed-supply: New mints the entire
// totalSupply to the caller once, at creation, and there is no mint
// path anywhere in this realm that can ever increase a symbol's supply
// afterward — same guarantee gno-token-minter's other design makes, just
// enforced by "no Mint function exists" per instance rather than "no
// Mint function exists in the realm."
//
// Anyone can call New with any symbol — first-come-first-served, no
// identity check tying a symbol to who it might suggest (e.g. calling
// New with symbol "BTC" doesn't mean anything beyond "someone claimed
// that symbol here first"). That's inherent to any public, permissionless
// token factory (the same is true of ERC20 factories on Ethereum), not
// a gap specific to this implementation — Render() surfaces each token's
// real creator address so anyone checking can verify it themselves
// rather than trusting the symbol/name alone.
package tokenfactory

import (
	unsaferealm "chain/runtime/unsafe"
	"chain"
	"errors"
	"math/overflow"
	"strconv"
	"strings"

	"gno.land/p/g1j2adx6ngvawtmkhq7eexsk9uq4u9zsrealpye2/avl"
)

const (
	TokenCreatedEvent = "TokenCreated"
	MintEvent         = "Mint"
	TransferEvent     = "Transfer"
	ApprovalEvent     = "Approval"
)

const (
	MaxNameLen   = 64
	MinSymbolLen = 1
	MaxSymbolLen = 10
	MaxDecimals  = 18
)

var (
	ErrInsufficientBalance   = errors.New("insufficient balance")
	ErrInsufficientAllowance = errors.New("insufficient allowance")
	ErrInvalidAddress        = errors.New("invalid address")
	ErrCannotTransferToSelf  = errors.New("cannot transfer to self")
	ErrInvalidAmount         = errors.New("invalid amount")
	ErrSymbolTaken           = errors.New("symbol already exists")
	ErrUnknownSymbol         = errors.New("unknown token symbol")
	ErrInvalidName           = errors.New("invalid token name (empty, too long, or contains control characters)")
	ErrInvalidSymbol         = errors.New("invalid symbol (must be 1-10 uppercase letters/digits)")
	ErrInvalidDecimals       = errors.New("invalid decimals (must be 0-18)")
	ErrInvalidSupply         = errors.New("invalid total supply (must be positive)")
)

// token is one fixed-supply token instance living inside this factory.
// Every field except balances/allowances is immutable after New() sets
// it — there is no admin, no owner, and no function anywhere in this
// file that can mint more of an already-created token.
type token struct {
	name        string
	symbol      string
	decimals    int
	totalSupply int64
	creator     address
	balances    avl.Tree // address string -> int64
	allowances  avl.Tree // "owner:spender" string -> int64
}

// instances holds every token this factory has ever created, keyed by
// symbol. Symbols are the public identity of a token here (there's no
// separate numeric ID) — chosen deliberately so URLs/render paths and
// every public function signature stay human-readable.
var instances avl.Tree // symbol -> *token

// callerAddress derives the address that crossed into whichever
// exported function called this. Uses chain/runtime/unsafe.PreviousRealm()
// instead of cur.Previous() for the same reason and under the same
// safety argument as gno-nft-minter's identical helper and this
// project's own token.gno: not available on every gno.land network
// (confirmed missing on Beta Mainnet's GnoVM), and every call site below
// is itself the sole crossing frame in its chain — no shared-helper
// reachable via multiple different realms' crossing paths.
func callerAddress() address {
	return unsaferealm.PreviousRealm().Address()
}

func validName(name string) bool {
	if name == "" || len(name) > MaxNameLen {
		return false
	}
	for _, c := range name {
		if c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

func validSymbol(symbol string) bool {
	if len(symbol) < MinSymbolLen || len(symbol) > MaxSymbolLen {
		return false
	}
	for _, c := range symbol {
		if !((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) {
			return false
		}
	}
	return true
}

// New creates a brand-new fixed-supply token and mints the entire
// totalSupply to the caller in the same call. Panics if the symbol is
// already taken, or if any argument fails validation — there is no
// partial-creation state to worry about since Gno rolls back the whole
// call on panic.
func New(cur realm, name, symbol string, decimals int, totalSupply int64) {
	if !validName(name) {
		panic(ErrInvalidName)
	}
	if !validSymbol(symbol) {
		panic(ErrInvalidSymbol)
	}
	if decimals < 0 || decimals > MaxDecimals {
		panic(ErrInvalidDecimals)
	}
	if totalSupply <= 0 {
		panic(ErrInvalidSupply)
	}
	if instances.Has(symbol) {
		panic(ErrSymbolTaken)
	}

	creator := callerAddress()
	t := &token{
		name:        name,
		symbol:      symbol,
		decimals:    decimals,
		totalSupply: totalSupply,
		creator:     creator,
	}
	t.balances.Set(creator.String(), totalSupply)
	instances.Set(symbol, t)

	chain.Emit(
		TokenCreatedEvent,
		"symbol", symbol,
		"name", name,
		"creator", creator.String(),
		"totalSupply", strconv.FormatInt(totalSupply, 10),
	)
	chain.Emit(
		MintEvent,
		"symbol", symbol,
		"to", creator.String(),
		"amount", strconv.FormatInt(totalSupply, 10),
	)
}

func mustGetToken(symbol string) *token {
	v := instances.Get(symbol)
	if v == nil {
		panic(ErrUnknownSymbol)
	}
	return v.(*token)
}

/* -------------------- Reader (standard GRC20-recognizable shape, symbol-scoped) -------------------- */

func Name(symbol string) string       { return mustGetToken(symbol).name }
func Symbol(symbol string) string     { return mustGetToken(symbol).symbol }
func Decimals(symbol string) int      { return mustGetToken(symbol).decimals }
func TotalSupply(symbol string) int64 { return mustGetToken(symbol).totalSupply }
func Creator(symbol string) address   { return mustGetToken(symbol).creator }

func BalanceOf(symbol string, addr address) int64 {
	return mustGetToken(symbol).balanceOf(addr)
}

func Allowance(symbol string, owner, spender address) int64 {
	t := mustGetToken(symbol)
	v := t.allowances.Get(allowanceKey(owner, spender))
	if v == nil {
		return 0
	}
	return v.(int64)
}

func allowanceKey(owner, spender address) string {
	return owner.String() + ":" + spender.String()
}

// TokenCount reports how many distinct tokens this factory has created,
// across every symbol, since it was deployed.
func TokenCount() int {
	return instances.Size()
}

/* ------------------------------- Writes ---------------------------------- */

// Transfer moves amount of the named token from the caller to `to`.
func Transfer(cur realm, symbol string, to address, amount int64) error {
	return mustGetToken(symbol).transfer(callerAddress(), to, amount)
}

// Approve sets the amount spender is allowed to move on the caller's
// behalf for the named token, replacing any previous allowance
// (standard GRC20/ERC20 semantics — not additive).
func Approve(cur realm, symbol string, spender address, amount int64) error {
	t := mustGetToken(symbol)
	owner := callerAddress()
	if !spender.IsValid() {
		return ErrInvalidAddress
	}
	if amount < 0 {
		return ErrInvalidAmount
	}
	t.allowances.Set(allowanceKey(owner, spender), amount)
	chain.Emit(
		ApprovalEvent,
		"symbol", symbol,
		"owner", owner.String(),
		"spender", spender.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return nil
}

// TransferFrom moves amount of the named token from `from` to `to`,
// spending part of the caller's allowance from `from`.
func TransferFrom(cur realm, symbol string, from, to address, amount int64) error {
	t := mustGetToken(symbol)
	spender := callerAddress()
	key := allowanceKey(from, spender)
	current := int64(0)
	if v := t.allowances.Get(key); v != nil {
		current = v.(int64)
	}
	if current < amount {
		return ErrInsufficientAllowance
	}
	if err := t.transfer(from, to, amount); err != nil {
		return err
	}
	t.allowances.Set(key, current-amount)
	return nil
}

func (t *token) balanceOf(addr address) int64 {
	v := t.balances.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// transfer is the shared move-balance logic for both Transfer and
// TransferFrom, scoped to this one token instance — a bug here can
// never cross into a different symbol's balances/allowances trees,
// since each token owns its own.
func (t *token) transfer(from, to address, amount int64) error {
	if !to.IsValid() {
		return ErrInvalidAddress
	}
	if from == to {
		return ErrCannotTransferToSelf
	}
	if amount <= 0 {
		return ErrInvalidAmount
	}
	fromBal := t.balanceOf(from)
	if fromBal < amount {
		return ErrInsufficientBalance
	}
	// Sub64p/Add64p panic on overflow rather than silently wrapping —
	// defensive redundancy here (the fromBal < amount check above
	// already rules out underflow, and a single balance can never
	// exceed the token's own fixed totalSupply), matching the same
	// belt-and-suspenders pattern gno-nft-minter's grc721 package uses.
	t.balances.Set(from.String(), overflow.Sub64p(fromBal, amount))
	t.balances.Set(to.String(), overflow.Add64p(t.balanceOf(to), amount))
	chain.Emit(
		TransferEvent,
		"symbol", t.symbol,
		"from", from.String(),
		"to", to.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return nil
}

/* ------------------------------- Render ---------------------------------- */

func Render(path string) string {
	if path == "" {
		var b strings.Builder
		b.WriteString("# Token Factory\n\n")
		b.WriteString(strconv.Itoa(instances.Size()) + " token(s) created.\n\n")
		instances.Iterate("", "", func(symbol string, v any) bool {
			t := v.(*token)
			b.WriteString("- **" + t.name + "** ($" + t.symbol + ") — created by " + t.creator.String() + "\n")
			return false
		})
		return b.String()
	}

	parts := strings.Split(path, "/")
	v := instances.Get(parts[0])
	if v == nil {
		return "404\n"
	}
	t := v.(*token)
	var b strings.Builder
	b.WriteString("# " + t.name + " ($" + t.symbol + ")\n\n")
	b.WriteString("* **Decimals**: " + strconv.Itoa(t.decimals) + "\n")
	b.WriteString("* **Total supply**: " + strconv.FormatInt(t.totalSupply, 10) + "\n")
	b.WriteString("* **Creator**: " + t.creator.String() + "\n")
	if len(parts) == 3 && parts[1] == "balance" {
		b.WriteString("* **" + parts[2] + " balance**: " + strconv.FormatInt(t.balanceOf(address(parts[2])), 10) + "\n")
	}
	return b.String()
}

package raffle

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"math/overflow"

	"gno.land/p/g16m0r7rm7fv5hx0ekr7gvx8g4fr7eu08nzhk6gt/commitreveal"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

type RaffleStatus int

const (
	StatusOpen RaffleStatus = iota
	StatusSettled
	StatusRefunding
)

func (s RaffleStatus) String() string {
	switch s {
	case StatusOpen:
		return "Open"
	case StatusSettled:
		return "Settled"
	case StatusRefunding:
		return "Refunding"
	default:
		return "Unknown"
	}
}

type Raffle struct {
	ID                   int64
	Organizer            address
	TicketPrice          int64
	MaxTickets           int64
	TicketsSold          int64
	CommitHash           [32]byte
	OrganizerFeeBps      int64
	SaleEndHeight        int64
	RevealDeadlineHeight int64
	Status               RaffleStatus
	Winner               address
	Buyers               *avl.Tree
	TicketIndexToBuyer   *avl.Tree
	Refunded             *avl.Tree
}

var (
	raffles      = avl.NewTree()
	nextRaffleID int64
)

func CreateRaffle(cur realm, commitHash [32]byte, ticketPrice int64, maxTickets int64, organizerFeeBps int64, saleDurationBlocks int64, revealWindowBlocks int64) int64 {
	if !cur.Previous().IsUserCall() {
		panic("raffle: only direct user calls can create a raffle")
	}
	if ticketPrice <= 0 {
		panic("raffle: ticketPrice must be positive")
	}
	if maxTickets <= 0 {
		panic("raffle: maxTickets must be positive")
	}
	if organizerFeeBps < 0 || organizerFeeBps > 10000 {
		panic("raffle: organizerFeeBps must be between 0 and 10000")
	}
	if saleDurationBlocks <= 0 {
		panic("raffle: saleDurationBlocks must be positive")
	}
	if revealWindowBlocks <= 0 {
		panic("raffle: revealWindowBlocks must be positive")
	}

	organizer := cur.Previous().Address()
	nowHeight := runtime.ChainHeight()
	saleEnd := nowHeight + saleDurationBlocks

	nextRaffleID++
	id := nextRaffleID

	r := &Raffle{
		ID:                   id,
		Organizer:            organizer,
		TicketPrice:          ticketPrice,
		MaxTickets:           maxTickets,
		CommitHash:           commitHash,
		OrganizerFeeBps:      organizerFeeBps,
		SaleEndHeight:        saleEnd,
		RevealDeadlineHeight: saleEnd + revealWindowBlocks,
		Status:               StatusOpen,
		Buyers:               avl.NewTree(),
		TicketIndexToBuyer:   avl.NewTree(),
		Refunded:             avl.NewTree(),
	}

	raffles.Set(itoa(id), r)
	return id
}

func BuyTicket(cur realm, raffleID int64) {
	if !cur.Previous().IsUserCall() {
		panic("raffle: only direct user calls can buy a ticket")
	}

	r := mustGetRaffle(raffleID)
	buyer := cur.Previous().Address()

	if r.Status != StatusOpen {
		panic("raffle: raffle is not open (status=" + r.Status.String() + ")")
	}
	if runtime.ChainHeight() >= r.SaleEndHeight {
		panic("raffle: ticket sale has ended")
	}
	if r.TicketsSold >= r.MaxTickets {
		panic("raffle: all tickets have been sold")
	}
	if r.Buyers.Get(buyer.String()) != nil {
		panic("raffle: this address has already bought a ticket")
	}

	sent := unsafe.OriginSend()
	amount := sent.AmountOf("ugnot")
	if amount != r.TicketPrice {
		panic("raffle: sent amount must exactly match the ticket price")
	}

	index := r.TicketsSold
	r.Buyers.Set(buyer.String(), index)
	r.TicketIndexToBuyer.Set(itoa(index), buyer.String())
	r.TicketsSold++
}

func RevealAndSettle(cur realm, raffleID int64, salt []byte, data []byte) {
	if !cur.Previous().IsUserCall() {
		panic("raffle: only direct user calls can reveal and settle")
	}

	r := mustGetRaffle(raffleID)
	caller := cur.Previous().Address()

	if caller != r.Organizer {
		panic("raffle: only the organizer can reveal and settle")
	}
	if r.Status != StatusOpen {
		panic("raffle: raffle is not open (status=" + r.Status.String() + ")")
	}
	nowHeight := runtime.ChainHeight()
	if nowHeight < r.SaleEndHeight {
		panic("raffle: ticket sale has not ended yet")
	}
	if nowHeight >= r.RevealDeadlineHeight {
		panic("raffle: reveal deadline has passed")
	}
	if !commitreveal.Verify(r.CommitHash, salt, data) {
		panic("raffle: revealed salt/data does not match the commitment")
	}

	if r.TicketsSold == 0 {
		r.Status = StatusSettled
		return
	}

	winnerIndex := deriveWinnerIndex(data, r.TicketsSold)
	rawWinner := r.TicketIndexToBuyer.Get(itoa(winnerIndex))
	if rawWinner == nil {
		panic("raffle: internal error, winner index has no buyer")
	}
	winnerAddrStr, ok := rawWinner.(string)
	if !ok {
		panic("raffle: internal error, corrupted buyer entry")
	}
	winner := address(winnerAddrStr)

	pot, ok := overflow.Mul64(r.TicketsSold, r.TicketPrice)
	if !ok {
		panic("raffle: internal error, pot calculation overflowed")
	}

	feeProduct, ok := overflow.Mul64(pot, r.OrganizerFeeBps)
	if !ok {
		panic("raffle: internal error, fee calculation overflowed")
	}
	organizerCut := feeProduct / 10000
	winnerPayout := pot - organizerCut

	r.Status = StatusSettled
	r.Winner = winner

	if organizerCut > 0 {
		payout(cur, r.Organizer, organizerCut)
	}
	if winnerPayout > 0 {
		payout(cur, winner, winnerPayout)
	}
}

func ReclaimRefund(cur realm, raffleID int64) {
	if !cur.Previous().IsUserCall() {
		panic("raffle: only direct user calls can reclaim a refund")
	}

	r := mustGetRaffle(raffleID)
	buyer := cur.Previous().Address()

	if r.Status == StatusSettled {
		panic("raffle: raffle already settled, no refunds available")
	}
	if runtime.ChainHeight() < r.RevealDeadlineHeight {
		panic("raffle: reveal deadline has not passed yet")
	}
	if r.Buyers.Get(buyer.String()) == nil {
		panic("raffle: caller did not buy a ticket for this raffle")
	}
	if r.Refunded.Get(buyer.String()) != nil {
		panic("raffle: caller has already reclaimed their refund")
	}

	r.Status = StatusRefunding
	r.Refunded.Set(buyer.String(), true)

	payout(cur, buyer, r.TicketPrice)
}

func deriveWinnerIndex(data []byte, ticketsSold int64) int64 {
	h := sha256.Sum256(data)
	var n uint64
	for i := 0; i < 8; i++ {
		n = n<<8 | uint64(h[i])
	}
	return int64(n % uint64(ticketsSold))
}

func mustGetRaffle(raffleID int64) *Raffle {
	raw := raffles.Get(itoa(raffleID))
	if raw == nil {
		panic("raffle: raffle not found")
	}
	r, ok := raw.(*Raffle)
	if !ok {
		panic("raffle: internal error, corrupted raffle entry")
	}
	return r
}

func payout(cur realm, to address, amount int64) {
	realmAddr := cur.Address()
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)

	have := b.GetCoins(realmAddr).AmountOf("ugnot")
	if have < amount {
		panic("raffle: internal invariant violation, insufficient realm balance for payout")
	}

	b.SendCoins(realmAddr, to, chain.Coins{chain.NewCoin("ugnot", amount)})
}

func itoa(i int64) string {
	return ufmt.Sprintf("%d", i)
}

func GetRaffleStatus(raffleID int64) string {
	return mustGetRaffle(raffleID).Status.String()
}

func GetRaffleOrganizer(raffleID int64) address {
	return mustGetRaffle(raffleID).Organizer
}

func GetTicketsSold(raffleID int64) int64 {
	return mustGetRaffle(raffleID).TicketsSold
}

func GetRaffleWinner(raffleID int64) address {
	return mustGetRaffle(raffleID).Winner
}

func GetSaleEndHeight(raffleID int64) int64 {
	return mustGetRaffle(raffleID).SaleEndHeight
}

func GetRevealDeadlineHeight(raffleID int64) int64 {
	return mustGetRaffle(raffleID).RevealDeadlineHeight
}

func HasBoughtTicket(raffleID int64, addr address) bool {
	return mustGetRaffle(raffleID).Buyers.Get(addr.String()) != nil
}

// Package tipjar is a public tip jar. Anyone can send real ugnot with an
// optional message via Tip; the realm keeps a running leaderboard of the
// most generous tippers and a feed of the most recent tips, both shown in
// Render. Only the deployer (captured as owner at init time) can Withdraw
// the accumulated balance. State-mutating functions are crossing functions
// (`cur realm`) per the gno 0.9 interrealm convention.
package tipjar

import (
	"sort"
	"strconv"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

const (
	denom         = "ugnot"
	maxRecent     = 10
	maxMessageLen = 140
)

// tipperStats is the persisted, accumulated record for one tipper.
type tipperStats struct {
	addr        address
	total       int64
	count       int
	lastMessage string
	lastHeight  int64
}

// tipEntry is one line in the recent-tips feed.
type tipEntry struct {
	from    address
	amount  int64
	message string
	height  int64
}

var (
	owner address // captured deployer, set once in init

	tippers avl.Tree // address string -> *tipperStats
	recent  []tipEntry

	totalReceived int64
	withdrawn     int64
	tipCount      int
)

func init() {
	owner = unsafe.OriginCaller()
}

// get returns the stored *tipperStats for addr, creating one if absent.
func get(addr address) *tipperStats {
	key := addr.String()
	if v := tippers.Get(key); v != nil {
		return v.(*tipperStats)
	}
	ts := &tipperStats{addr: addr}
	tippers.Set(key, ts)
	return ts
}

// Tip credits the caller's OriginSend ugnot to the jar and records it
// against their running total. Only an EOA calling directly via MsgCall may
// tip — see the payment-guard note on IsUserCall vs IsUser.
func Tip(cur realm, message string) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("only an EOA via MsgCall can tip")
	}
	if len(message) > maxMessageLen {
		panic("message too long (max " + strconv.Itoa(maxMessageLen) + " chars)")
	}

	amount := unsafe.OriginSend().AmountOf(denom)
	if amount <= 0 {
		panic("send some ugnot to tip")
	}

	from := prev.Address()
	height := runtime.ChainHeight()

	ts := get(from)
	ts.total += amount
	ts.count++
	ts.lastMessage = message
	ts.lastHeight = height

	totalReceived += amount
	tipCount++

	recent = append(recent, tipEntry{from: from, amount: amount, message: message, height: height})
	if len(recent) > maxRecent {
		recent = recent[len(recent)-maxRecent:]
	}

	chain.Emit("Tip", "from", from.String(), "amount", strconv.FormatInt(amount, 10), "message", message)
	return "thanks for the " + strconv.FormatInt(amount, 10) + "ugnot tip!"
}

// Balance reports the ugnot still held by the jar (received minus withdrawn).
func Balance() int64 {
	return totalReceived - withdrawn
}

// Withdraw sends amount ugnot from the jar to the owner. Owner-only.
func Withdraw(cur realm, amount int64) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if cur.Previous().Address() != owner {
		panic("only the owner can withdraw")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > Balance() {
		panic("amount exceeds available balance")
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), owner, chain.NewCoins(chain.NewCoin(denom, amount)))
	withdrawn += amount

	chain.Emit("Withdraw", "amount", strconv.FormatInt(amount, 10))
}

// byTotal implements sort.Interface, ranking tippers by total tipped
// descending, ties broken by tip count then address for a fully
// deterministic order.
type byTotal struct {
	stats []*tipperStats
}

func (b byTotal) Len() int      { return len(b.stats) }
func (b byTotal) Swap(i, j int) { b.stats[i], b.stats[j] = b.stats[j], b.stats[i] }
func (b byTotal) Less(i, j int) bool {
	if b.stats[i].total != b.stats[j].total {
		return b.stats[i].total > b.stats[j].total
	}
	if b.stats[i].count != b.stats[j].count {
		return b.stats[i].count > b.stats[j].count
	}
	return b.stats[i].addr.String() < b.stats[j].addr.String()
}

// leaderboard collects all tippers ranked by total tipped descending.
func leaderboard() []*tipperStats {
	stats := make([]*tipperStats, 0, tippers.Size())
	tippers.Iterate("", "", func(_ string, v any) bool {
		stats = append(stats, v.(*tipperStats))
		return false
	})
	sort.Stable(byTotal{stats: stats})
	return stats
}

// medal returns the emoji for a given zero-based rank, or "" past the podium.
func medal(rank int) string {
	switch rank {
	case 0:
		return "🥇"
	case 1:
		return "🥈"
	case 2:
		return "🥉"
	default:
		return ""
	}
}

// display returns a shortened address for table display.
func display(addr address) string {
	s := addr.String()
	if len(s) > 12 {
		return s[:8] + "…" + s[len(s)-4:]
	}
	return s
}

// Render shows the jar's balance, the tipper leaderboard, and a feed of the
// most recent tips.
func Render(path string) string {
	out := "# 🫙 Tip Jar\n\n"
	out += "Send ugnot with `Tip(message)` to leave a tip and a note. " +
		"The owner can withdraw the accumulated balance with `Withdraw(amount)`.\n\n"

	out += "**Balance:** " + strconv.FormatInt(Balance(), 10) + "ugnot" +
		"  ·  **Total tips:** " + strconv.Itoa(tipCount) +
		"  ·  **All-time received:** " + strconv.FormatInt(totalReceived, 10) + "ugnot\n\n"

	stats := leaderboard()
	out += "## Leaderboard\n\n"
	if len(stats) == 0 {
		out += "_No tips yet. Be the first!_\n\n"
	} else {
		out += "| Rank | Tipper | Total tipped | Tips |\n"
		out += "| ---: | :--- | ---: | ---: |\n"
		for i, ts := range stats {
			rankCell := medal(i)
			if rankCell == "" {
				rankCell = strconv.Itoa(i + 1)
			}
			out += "| " + rankCell +
				" | " + display(ts.addr) +
				" | " + strconv.FormatInt(ts.total, 10) + "ugnot" +
				" | " + strconv.Itoa(ts.count) + " |\n"
		}
		out += "\n"
	}

	out += "## Recent tips\n\n"
	if len(recent) == 0 {
		out += "_Nothing yet._\n"
		return out
	}
	for i := len(recent) - 1; i >= 0; i-- {
		e := recent[i]
		out += "- **" + display(e.from) + "** tipped " + strconv.FormatInt(e.amount, 10) +
			"ugnot at block " + strconv.FormatInt(e.height, 10)
		if e.message != "" {
			out += ": _" + e.message + "_"
		}
		out += "\n"
	}
	return out
}
